-- Lernfeld:1 > Das Unternehmen und die eigene Rolle im Betrieb beschreiben > Die eigene Rolle > IT-Ausbildungsberufe > Systemintegration
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Systemintegrator einen Server ohne Programmierkenntnisse einrichten?', 2, '[{"text": "Ja", "correct": true, "because": "Konfiguration ist oft GUI-basiert"}, {"text": "Nein", "correct": false, "because": "Scripting ist aber hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Systemintegrator auch Software entwickeln?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Integration, nicht Entwicklung"}, {"text": "Ja", "correct": false, "because": "Entwicklung ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Netzwerkkonfiguration eine Kernaufgabe für Systemintegratoren?', 2, '[{"text": "Ja", "correct": true, "because": "Netzwerke sind essenziell"}, {"text": "Nein", "correct": false, "because": "Kann nicht ausgeschlossen werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Systemintegrator nur mit Hardware arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Softwareintegration ist zentral"}, {"text": "Ja", "correct": false, "because": "Hardware allein reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Muss ich als Systemintegrator Linux beherrschen?', 2, '[{"text": "Nein", "correct": true, "because": "Windows kann reichen, aber Linux hilft"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Systemintegrator auch Cloud-Systeme einrichten?', 2, '[{"text": "Ja", "correct": true, "because": "Cloud ist Teil moderner IT"}, {"text": "Nein", "correct": false, "because": "Cloud gehört dazu"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Troubleshooting eine Hauptaufgabe für Systemintegratoren?', 2, '[{"text": "Ja", "correct": true, "because": "Problemlösung ist Kernkompetenz"}, {"text": "Nein", "correct": false, "because": "Unvermeidlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich als Systemintegrator ohne Kundenkontakt arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Abstimmung mit Nutzern nötig"}, {"text": "Ja", "correct": false, "because": "Kontakt oft erforderlich"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem muss ein Systemintegrator oft konfigurieren?', 2, '[{"text": "Windows Server", "correct": true, "because": "Weit verbreitet in Firmen"}, {"text": "iOS", "correct": false, "because": "Mobilgeräte"}, {"text": "Photoshop", "correct": false, "because": "Keine OS"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter will, dass ich ein Backup-System einrichte. Was ist der erste Schritt?', 3, '[{"text": "Anforderungen klären", "correct": true, "because": "Basis für Planung"}, {"text": "Hardware kaufen", "correct": false, "because": "Zu früh"}, {"text": "Software installieren", "correct": false, "because": "Ohne Plan riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt ein Systemintegrator oft für Remote-Zugriff?', 2, '[{"text": "SSH", "correct": true, "because": "Sicher und Standard"}, {"text": "HTTP", "correct": false, "because": "Webzugriff"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin will ein neues WLAN im Büro. Was prüfe ich zuerst?', 3, '[{"text": "Abdeckung planen", "correct": true, "because": "Reichweite entscheidend"}, {"text": "Router kaufen", "correct": false, "because": "Planung fehlt"}, {"text": "Passwort setzen", "correct": false, "because": "Zu früh"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein Systemintegrator?', 4, '[{"text": "Server einrichten", "correct": true, "because": "Kernaufgabe"}, {"text": "Netzwerke konfigurieren", "correct": true, "because": "Teil der Integration"}, {"text": "Systeme warten", "correct": true, "because": "Support gehört dazu"}, {"text": "Apps programmieren", "correct": false, "because": "Entwickleraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Einrichtung eines neuen Systems?', 3, '[{"text": "Hardware-Installation", "correct": true, "because": "Physische Basis"}, {"text": "Software-Konfiguration", "correct": true, "because": "Funktionalität"}, {"text": "Tests", "correct": true, "because": "Sicherstellung"}, {"text": "Marketing", "correct": false, "because": "Andere Abteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben ein Problem mit dem Drucker im Netzwerk. Was könnte ich als Systemintegrator prüfen?', 3, '[{"text": "IP-Adresse", "correct": true, "because": "Netzwerkzugriff"}, {"text": "Treiber", "correct": true, "because": "Softwareproblem"}, {"text": "Verbindung", "correct": true, "because": "Physische Ebene"}, {"text": "Papierqualität", "correct": false, "because": "Nicht IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools nutzt ein Systemintegrator häufig?', 4, '[{"text": "PuTTY", "correct": true, "because": "SSH-Zugriff"}, {"text": "Wireshark", "correct": true, "because": "Netzwerkanalyse"}, {"text": "PowerShell", "correct": true, "because": "Skripte"}, {"text": "Word", "correct": false, "because": "Bürosoftware"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Systemintegratoren richten Backup-Systeme ein. b) Sie müssen auch Webseiten designen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Design nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Troubleshooting gehört zu Systemintegration. b) Hardware-Wissen ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Troubleshooting ja, Hardware nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Systemintegrator kann Virtualisierung einsetzen. b) Er arbeitet nie mit Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Virtualisierung ja, Kunden oft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemintegratoren konfigurieren Netzwerke. b) Sie brauchen keine Dokumentation zu schreiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerke ja, Doku nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

